#include <bits/stdc++.h>
using namespace std;

long long solve(long long n) {
    static unordered_map<long long, long long> cache;
    if (cache.find(n) != cache.end()) return cache[n];
    if (n <= 11) return min(n, 2 + (11 - n));
    long long val = 1, count = 1;
    while (val <= n) {
        val = val * 10 + 1;
        count++;
    }
    long long limit = val / 10;
    if (val > 2 * n) {
        long long quotient = n / limit;
        long long rem = n % limit;
        long long res1 = solve(val - n) + count;
        long long res2 = quotient * (count - 1) + solve(rem);
        return cache[n] = min(res1, res2);
    } else {
        long long quotient = n / limit;
        long long rem = n % limit;
        long long res1 = solve(val - n) + count;
        long long res2 = quotient * (count - 1) + solve(rem);
        return cache[n] = min(res1, res2);
    }
}

int main() {
    long long input;
    cin >> input;
    cout << solve(input);
    return 0;
}
